export interface SolveGraphRequest {
    /** Name of the graph resource to solve. */
    graph_name: string;
    /**
     * Additional weights to apply to the edges of an existing graph. Weights
     * must be specified using identifiers; identifiers are grouped as
     * combinations. Identifiers can be used with existing column names, e.g.,
     * 'table.column AS WEIGHTS_EDGE_ID', expressions, e.g., 'ST_LENGTH(wkt) AS
     * WEIGHTS_VALUESPECIFIED', or constant values, e.g., '{4, 15, 2} AS
     * WEIGHTS_VALUESPECIFIED'. Any provided weights will be added (in the case
     * of 'WEIGHTS_VALUESPECIFIED') to or multiplied with (in the case of
     * 'WEIGHTS_FACTORSPECIFIED') the existing weight(s). If using constant
     * values in an identifier combination, the number of values specified must
     * match across the combination.
     */
    weights_on_edges?: string[];
    /**
     * Additional restrictions to apply to the nodes/edges of an existing
     * graph. Restrictions must be specified using identifiers; identifiers are
     * grouped as combinations. Identifiers can be used with existing column
     * names, e.g., 'table.column AS RESTRICTIONS_EDGE_ID', expressions, e.g.,
     * 'column/2 AS RESTRICTIONS_VALUECOMPARED', or constant values, e.g., '{0,
     * 0, 0, 1} AS RESTRICTIONS_ONOFFCOMPARED'. If using constant values in an
     * identifier combination, the number of values specified must match across
     * the combination. If remove_previous_restrictions option is set to true,
     * any provided restrictions will replace the existing restrictions.
     * Otherwise, any provided restrictions will be added (in the case of
     * 'RESTRICTIONS_VALUECOMPARED') to or replaced (in the case of
     * 'RESTRICTIONS_ONOFFCOMPARED').
     */
    restrictions?: string[];
    /** The type of solver to use for the graph. */
    solver_type?: string;
    /** It can be one of the nodal identifiers - e.g: 'NODE_WKTPOINT' for source nodes. For BACKHAUL_ROUTING, this list depicts the fixed assets. */
    source_nodes?: string[];
    /** It can be one of the nodal identifiers - e.g: 'NODE_WKTPOINT' for destination (target) nodes. For BACKHAUL_ROUTING, this list depicts the remote assets. */
    destination_nodes?: string[];
    /** Name of the table to store the solution, in [schema_name.]table_name format, using standard name resolution rules. */
    solution_table?: string;
    /** Additional parameters. */
    options?: Record<string, string>;
}

