export interface VisualizeImageLabelsRequest {
    /** Name of the table containing the data defining the labels to render. */
    table_name: string;
    /** Double, float or decimal expression that evaluates to the x coordinates of the center points of the labels. */
    x_column_name: string;
    /** Double, float or decimal expression that evaluates to the y coordinates of the center points of the labels. */
    y_column_name: string;
    /** Numeric expression that evaluates to the number of output pixels by which the labels will be offset horizontally from their specified x coordinates. If blank, an offset of 0 will be used. */
    x_offset?: string;
    /** Numeric expression that evaluates to the number of output pixels by which the labels will be offset vertically from their specified y coordinates. If blank, an offset of 0 will be used. */
    y_offset?: string;
    /** Expression that evaluates to the text for the labels. */
    text_string: string;
    /** Expression that evaluates to the fonts for the labels. If blank, a default system font will be used. */
    font?: string;
    /** Numeric expression that evaluates to the text color for the labels. If blank, opaque black will be used. */
    text_color?: string;
    /** Numeric expression that evaluates to the angle of clockwise rotation (in degrees) for the labels. If blank, an angle of 0 will be used. */
    text_angle?: string;
    /** Numeric expression that evaluates to the scaling factor for the labels. (1 is normal size, 0.5 is half size, 2 is double size, etc.) If blank, a scaling factor of 1 will be used. */
    text_scale?: string;
    /** Boolean expression indicating whether boxes will be drawn around the labels. If blank, no boxes will be drawn. */
    draw_box?: string;
    /** Boolean expression indicating whether leader lines will be drawn from the labels to points specified using `leader_x_column_name` and `leader_y_column_name`. If blank, no leader lines will be drawn. */
    draw_leader?: string;
    /** Numeric expression that evaluates to the line width in output pixels for the labels' boxes and leader lines. If blank, a line width of 1 will be used. */
    line_width?: string;
    /** Numeric expression that evaluates to the line color for the labels' boxes and leader lines. If blank, opaque black will be used. */
    line_color?: string;
    /** Numeric expression that evaluates to the fill color for the labels' boxes. If blank, the boxes will not be filled. */
    fill_color?: string;
    /** Double, float or decimal expression that evaluates to the x coordinates of the points to which the labels' leader lines will be drawn. May be left blank if no leader lines are to be drawn. */
    leader_x_column_name?: string;
    /** Double, float or decimal expression that evaluates to the y coordinates of the points to which the labels' leader lines will be drawn. May be left blank if no leader lines are to be drawn. */
    leader_y_column_name?: string;
    /** Boolean expression indicating which labels to include in the image. If blank, all labels will be included. */
    filter?: string;
    /** Lower bound for the x coordinates of labels to include in the image. */
    min_x: number;
    /** Upper bound for the x coordinates of labels to include in the image. */
    max_x: number;
    /** Lower bound for the y coordinates of labels to include in the image. */
    min_y: number;
    /** Upper bound for the y coordinates of labels to include in the image. */
    max_y: number;
    /** Width of the generated image. */
    width: number;
    /** Height of the generated image. */
    height: number;
    /** Spatial Reference System (i.e. EPSG Code). */
    projection?: string;
    /** Optional parameters. */
    options?: Record<string, string>;
}

